using Godot;
using System;
public partial class ImageWorkspaceOperations
{
    private readonly ImageInlineTextOperations _inlineText=new();
    public void font_menu(Control owner)
    {
        var layer=main_layer(owner);if(layer==null)return;var popup=new PopupPanel();popup.AddThemeStyleboxOverride("panel",box(new Color("14202c"),new Color("4a706d"),10,12));owner.AddChild(popup);var column=new VBoxContainer{CustomMinimumSize=new Vector2(350,400)};popup.AddChild(column);var search=new LineEdit{PlaceholderText="Search installed fonts…"};column.AddChild(search);var actual=new CheckButton{Text="Preview with layer text"};column.AddChild(actual);var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};column.AddChild(scroll);var list=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(list);var fonts=OS.GetSystemFonts();Array.Sort(fonts,StringComparer.Ordinal);void Populate(string query){clear(list);int count=0;foreach(string family in fonts){if(query.Length>0&&!family.Contains(query,StringComparison.OrdinalIgnoreCase))continue;string selected=family;var button=this.button(owner,list,actual.ButtonPressed?Get(layer.Get("properties").AsGodotDictionary(),"text","Text").AsString():family,Callable.From(()=>{Action(owner,()=>set_text_setting(layer,"font",selected));popup.Hide();}),"","");button.TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis;button.TooltipText=family;button.AddThemeFontOverride("font",new SystemFont{FontNames=new[]{family}});if(++count>=60)break;}}search.TextChanged+=Populate;Populate("");actual.Toggled+=_=>Populate(search.Text);popup.PopupHide+=popup.QueueFree;popup.PopupCentered(new Vector2I(390,460));search.GrabFocus();
    }
    public void edit_canvas_text(Control owner)
    {
        var layer=main_layer(owner);if(layer==null||layer.Get("kind").AsString()!="text")return;begin(owner);owner.Set("_inline_text_layer_id",layer.Get("id"));var canvas=Canvas(owner);var editor=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_inline_text_edit.gd").New().As<TextEdit>();editor.Set("layer",layer);editor.Set("canvas",canvas);editor.Text=Get(layer.Get("properties").AsGodotDictionary(),"text","").AsString();canvas.AddChild(editor);editor.GrabFocus();editor.SetCaretLine(editor.GetLineCount()-1);int length=0;foreach(var rune in editor.GetLine(editor.GetLineCount()-1).EnumerateRunes())length++;editor.SetCaretColumn(length);_inlineText.place_caret(editor,_inlineText.hit_text(editor,editor.GetTransform().AffineInverse()*canvas.Get("_mouse").AsVector2()),-1);
        editor.Connect("navigation_requested",Callable.From<InputEventMouseButton>(input=>{using var forwarded=(InputEventMouseButton)input.Duplicate();forwarded.Position=editor.GetTransform()*input.Position;_canvas.input_canvas(canvas,forwarded);_inlineText.sync_layout(editor);}));editor.TextChanged+=()=>{layer.Get("properties").AsGodotDictionary()["text"]=editor.Text;preview(owner);};void Finish(bool cancelled){if(editor.IsQueuedForDeletion())return;owner.Set("_inline_text_layer_id","");editor.QueueFree();if(cancelled)cancel(owner);else commit(owner);}editor.FocusExited+=()=>Finish(false);editor.GuiInput+=input=>{if(input is InputEventKey key&&key.Pressed){if(key.Keycode==Key.Escape){editor.AcceptEvent();Finish(true);}else if(key.Keycode==Key.Enter&&key.CtrlPressed){editor.AcceptEvent();Finish(false);}}};
    }
}
